#!/usr/bin/env bash
# AI generated by: Claude Code / claude-opus-5-5
# Prompt: "i changed my mind could you host in on the t3-exec vm, its should be accessible through tailscale"
# Changes: Repeatable deploy – sync sources to the VM, build there, install to /opt/table-maker,
#          (re)start the systemd service and publish it on the tailnet with Tailscale Serve.
#
# Usage: tools/table-maker/deploy/deploy.sh [ssh-host]   (default: t3-exec)
set -euo pipefail

HOST="${1:-t3-exec}"
APP_DIR="$(cd "$(dirname "$0")/.." && pwd)"
BUILD_DIR='~/build/table-maker'
PORT=4310

echo "==> Syncing sources to $HOST"
ssh "$HOST" "mkdir -p $BUILD_DIR"
rsync -a --delete \
  --exclude node_modules --exclude .output --exclude data --exclude .tanstack --exclude .nitro \
  "$APP_DIR/" "$HOST:${BUILD_DIR#\~/}/"

echo "==> Building and installing on $HOST"
ssh "$HOST" bash -s <<EOF
set -euo pipefail
cd $BUILD_DIR
npm ci --no-audit --no-fund
npm run typecheck
npm run build
sudo install -d -m 755 /opt/table-maker
sudo rsync -a --delete .output/ /opt/table-maker/
sudo install -m 644 deploy/table-maker.service /etc/systemd/system/table-maker.service
sudo systemctl daemon-reload
sudo systemctl enable table-maker.service >/dev/null
sudo systemctl restart table-maker.service
for i in \$(seq 1 20); do
  curl -fs -o /dev/null http://127.0.0.1:$PORT/ 2>/dev/null && break
  sleep 0.5
done
curl -fsS -o /dev/null http://127.0.0.1:$PORT/ || { sudo journalctl -u table-maker -n 50 --no-pager; exit 1; }
sudo tailscale serve --bg --https=$PORT http://127.0.0.1:$PORT >/dev/null
echo "Deployed: https://\$(tailscale status --json | python3 -c 'import json,sys; print(json.load(sys.stdin)["Self"]["DNSName"].rstrip("."))'):$PORT/"
EOF
